"""Checks the manual pages in man/ (#581).

    check-man.py SACDFS_BINARY MAN_DIR OPTIONS_MD

SACDFS_BINARY is built with `--features man,nfs`. It writes the pages again into a temporary
folder, and they must equal the committed ones byte for byte (regenerate them with
`target/debug/sacdfs --generate-man-pages man`). Then every page must render without a
warning from groff, if groff is installed, and the long options of sacdfs(1) must be those
that OPTIONS_MD (docs/options.md) lists, in its three tables. Exits with status 1, listing
every difference.
"""

import re
import subprocess
import sys
import tempfile
from pathlib import Path


def man_options(text: str) -> set[str]:
    """The long options a generated page documents: OPTIONS, and DEPRECATED OPTIONS."""
    found: set[str] = set()
    section = ""
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if line.startswith(".SH"):
            section = line[4:].strip('" ')
        elif line == ".TP" and section in ("OPTIONS", "DEPRECATED OPTIONS") and i + 1 < len(lines):
            # `\fB\-f\fR, \fB\-\-foreground\fR ...` (generated) or `.B \-\-lookup\-name` (written)
            found.update(re.findall(r"(?:\\fB|^\.B )((?:\\-){2}[a-z0-9](?:[a-z0-9]|\\-)*)", lines[i + 1]))
    return {o.replace("\\-", "-").removeprefix("--") for o in found}


def doc_options(text: str) -> set[str]:
    """The long options in the first column of every table of docs/options.md."""
    return {
        m
        for line in text.splitlines()
        if line.startswith("| `")
        for m in re.findall(r"`--([a-z0-9-]+)", re.split(r"(?<!\\)\|", line)[1])
    }


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print(__doc__.strip().splitlines()[2].strip(), file=sys.stderr)
        return 2
    binary, man, options = argv[0], Path(argv[1]), Path(argv[2])
    errors: list[str] = []
    with tempfile.TemporaryDirectory() as tmp:
        subprocess.run([binary, "--generate-man-pages", tmp], check=True)
        fresh = {p.name: p.read_bytes() for p in Path(tmp).iterdir()}
    for name, data in sorted(fresh.items()):
        have = man / name
        if not have.is_file():
            errors.append(f"{name}: not in {man}")
        elif have.read_bytes() != data:
            errors.append(f"{name}: not current; regenerate with `sacdfs --generate-man-pages {man}`")
    pages = sorted(man.glob("*.[18]"))
    for page in pages:
        if page.name.endswith(".1") and page.name not in fresh:
            errors.append(f"{page.name}: not generated by this build (is `nfs` on?)")
    try:
        for page in pages:
            r = subprocess.run(
                ["groff", "-ww", "-z", "-man", "-Tutf8", str(page)], capture_output=True, text=True, check=False
            )
            # The wide synopsis of sacdfs-nfs(1) cannot always be adjusted: not an error.
            bad = [l for l in r.stderr.splitlines() if "cannot adjust line" not in l]
            errors.extend(f"{page.name}: groff: {l}" for l in bad)
    except FileNotFoundError:
        print("groff not installed: the pages were not rendered", file=sys.stderr)
    in_man = man_options((man / "sacdfs.1").read_text(encoding="utf-8"))
    in_doc = doc_options(options.read_text(encoding="utf-8"))
    for o in sorted(in_doc - in_man):
        errors.append(f"--{o} is in {options.name} and not in sacdfs.1")
    for o in sorted(in_man - in_doc):
        errors.append(f"--{o} is in sacdfs.1 and not in {options.name}")
    if errors:
        print("the manual pages are wrong:", file=sys.stderr)
        for e in errors:
            print("  " + e, file=sys.stderr)
        return 1
    print(f"manual pages are current: {len(pages)} pages, {len(in_man)} options in sacdfs.1")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
